/* Spark's authenticated experience. No backend secret is shipped to the browser. */
(() => {
  const cfg = window.SPARK_CONFIG;
  if (!cfg?.url || !cfg?.publishableKey) return;
  const $ = (selector) => document.querySelector(selector);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const state = {view:'discover', authMode:'login', pendingEmail:'', resendAvailableAt:0, session:null, user:null, profile:null, profiles:[], discoveryWeights:{}, connections:[], links:[], photos:[], blocks:[], galleryIndex:{}, isModerator:false, suspensions:[], reports:[], preferences:null, pausedIds:[], photoUrls:{}, photoLoading:new Set(), photoFailed:new Set(), messages:[], reactions:[], chatPrefs:[], chatSearch:'', unread:{}, latestMessages:{}, activeChat:null, selected:0, busy:false, sendingIntro:false, sendingMessage:false, activityPrivacy:null, privateEntitlement:null, pendingAttachment:null, mediaUrls:{}, mediaLoading:new Set(), recorder:null, recordingStream:null, recordChunks:[], recordStarted:0, notice:'', timer:null};
  const platforms=['Instagram','Facebook','YouTube','Snapchat','TikTok','Threads','X','Other'];
  const hosts={Instagram:['instagram.com','www.instagram.com'],Facebook:['facebook.com','www.facebook.com','m.facebook.com','fb.com','www.fb.com'],YouTube:['youtube.com','www.youtube.com','m.youtube.com','youtu.be'],Snapchat:['snapchat.com','www.snapchat.com'],TikTok:['tiktok.com','www.tiktok.com','m.tiktok.com'],Threads:['threads.net','www.threads.net'],X:['x.com','www.x.com','twitter.com','www.twitter.com']};
  const visibilityLabels={hidden:'Hidden',matches:'Matches only',members:'All signed-in members'};
  const interestOptions=['Music','Travel','Food','Books','Films','Fitness','Art','Gaming','Nature','Pets','Dancing','Coffee'];
  const promptOptions=['A perfect weekend looks like…','The quickest way to make me laugh…','A small thing I love…','Let’s talk about…'];
  function personalityHtml(p){const interests=Array.isArray(p.interests)?p.interests.filter(v=>interestOptions.includes(v)):[];return `${interests.length?`<div class="live-interest-tags" aria-label="Interests">${interests.map(v=>`<span>${esc(v)}</span>`).join('')}</div>`:''}${p.prompt_question&&p.prompt_answer?`<div class="live-prompt"><strong>${esc(p.prompt_question)}</strong><p>${esc(p.prompt_answer)}</p></div>`:''}`}

  function validatedSocialUrl(platform,raw){let url;try{url=new URL(String(raw).trim())}catch{throw new Error('Enter a complete HTTPS profile link.')}if(url.protocol!=='https:'||url.username||url.password||url.port||!(/^[a-z0-9][a-z0-9.-]*\.[a-z]{2,}$/i.test(url.hostname)))throw new Error('Use a valid HTTPS profile link without a login or port.');if(hosts[platform]&&!hosts[platform].includes(url.hostname.toLowerCase()))throw new Error(`Use a ${platform} profile link for ${platform}.`);return url.href}
  function socialLinksFor(owner){return state.links.filter(link=>link.owner_id===owner)}
  function socialLinksHtml(owner){const links=socialLinksFor(owner).filter(link=>owner!==state.user.id||link.visibility!=='hidden');return links.length?`<div class="live-social-links" aria-label="Social profiles">${links.map(link=>`<a href="${esc(link.url)}" target="_blank" rel="noopener noreferrer" title="Opens ${esc(link.platform)} outside Vibely"><span>${esc(link.platform)}</span><small>↗</small></a>`).join('')}</div><p class="live-social-disclaimer">Social links are added by members and are not identity verified.</p>`:''}
  const photoKey = p => p?.photo_path ? `${p.id}:${p.photo_path}` : null;
  const storagePath = path => path.split('/').map(encodeURIComponent).join('/');
  async function storageRequest(path,method='GET',body=null,contentType=null){
    if(state.session && Date.now()>((state.session.expires_at||0)-60)*1000)await renewSession();
    const response=await fetch(`${cfg.url}/storage/v1/object/${path}`,{method,headers:{apikey:cfg.publishableKey,Authorization:`Bearer ${state.session.access_token}`,...(contentType?{'Content-Type':contentType}:{})},body});
    if(!response.ok){let data;try{data=await response.json()}catch{}throw Error(data?.message||data?.error||`Media request failed (${response.status})`)}
    return response;
  }
  function forgetPhoto(p){const key=photoKey(p);if(key&&state.photoUrls[key]){URL.revokeObjectURL(state.photoUrls[key]);delete state.photoUrls[key]}if(key)state.photoFailed.delete(key)}
  function ensurePhoto(p){const key=photoKey(p);if(!key||state.photoUrls[key]||state.photoLoading.has(key)||state.photoFailed.has(key)||!state.session)return;
    state.photoLoading.add(key);storageRequest(`authenticated/spark-profile-photos/${storagePath(p.photo_path)}`).then(r=>r.blob()).then(blob=>{state.photoUrls[key]=URL.createObjectURL(blob);if(state.user&&state.profile)render()}).catch(()=>state.photoFailed.add(key)).finally(()=>state.photoLoading.delete(key));
  }
  function photoMarkup(p){const key=photoKey(p);if(key&&!state.photoUrls[key])ensurePhoto(p);return key&&state.photoUrls[key]?`<img class="live-photo" src="${esc(state.photoUrls[key])}" alt="Profile photo of ${esc(p.name)}">`:`<span class="live-initial">${esc(p.name.slice(0,1).toUpperCase())}</span>`}
  async function photoBlob(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12*1024*1024)throw Error('Choose a JPG, PNG, or WebP image under 12 MB.');
    const image=await createImageBitmap(file);const scale=Math.min(1,1600/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);image.close?.();
    const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.82));if(!blob||blob.size>5*1024*1024)throw Error('This photo could not be compressed under 5 MB. Try a smaller image.');return blob;
  }
  function galleryFor(owner){return state.photos.filter(photo=>photo.owner_id===owner).sort((a,b)=>a.slot-b.slot)}
  function chosenPhoto(p){const gallery=galleryFor(p.id);return gallery.find(photo=>photo.id===state.galleryIndex[p.id])?.path||p.photo_path||gallery[0]?.path||null}
  function galleryThumbsHtml(p){const gallery=galleryFor(p.id);if(gallery.length<2)return '';const selected=chosenPhoto(p);return `<div class="live-gallery-thumbs" aria-label="Photos of ${esc(p.name)}">${gallery.map((photo,i)=>{const key=photoKey({id:p.id,photo_path:photo.path});if(!state.photoUrls[key])ensurePhoto({...p,photo_path:photo.path});return `<button type="button" data-live="view-photo" data-id="${esc(photo.id)}" class="${photo.path===selected?'active':''}" aria-label="View photo ${i+1}">${state.photoUrls[key]?`<img src="${esc(state.photoUrls[key])}" alt="">`:i+1}</button>`}).join('')}</div>`}
  function photoGalleryHtml(p){const gallery=galleryFor(p.id);return `<section class="live-photo-editor"><span class="live-kicker">YOUR FIRST IMPRESSION</span><h2>Your photos <small>${gallery.length}/4</small></h2><p>Choose a cover photo and add up to four. Signed-in members can see your gallery unless you block them.</p><div class="live-gallery-grid">${gallery.map((photo,i)=>`<div class="live-gallery-tile"><div class="live-gallery-photo">${photoMarkup({...p,photo_path:photo.path})}</div><strong>${photo.path===p.photo_path?'Cover photo':`Photo ${i+1}`}</strong><div class="live-row">${photo.path===p.photo_path?'':`<button class="live-outline" data-live="cover-photo" data-id="${esc(photo.id)}">Make cover</button>`}<button class="live-outline" data-live="remove-photo" data-id="${esc(photo.id)}">Remove</button></div></div>`).join('')||'<p class="live-muted">Add your first photo to show more of yourself.</p>'}</div>${gallery.length<4?`<form id="livePhotoForm"><label for="livePhotoFile">Choose JPG, PNG or WebP</label><input id="livePhotoFile" name="photo" type="file" accept="image/jpeg,image/png,image/webp" required><button class="live-primary" type="submit" ${state.busy?'disabled':''}>${state.busy?'Saving…':'Add photo →'}</button></form>`:''}<small>Photos are resized to WebP before upload. Only add photos you have permission to use.</small></section>`}
  const saveSession = value => { state.session=value; if(value) localStorage.setItem('spark-live-session',JSON.stringify(value)); else localStorage.removeItem('spark-live-session'); };
  const notify = message => { state.notice=message; render(); };
  function askText(title,description,maxlength=300){return new Promise(resolve=>{const host=$('#modalRoot');host.innerHTML=`<div class="modal-backdrop"><form class="modal live-dialog" id="liveTextModal" role="dialog" aria-modal="true"><div class="modal-icon">✦</div><h2>${esc(title)}</h2><p class="modal-sub">${esc(description)}</p><label class="form-label" for="liveDialogText">Your note</label><textarea id="liveDialogText" class="form-control" maxlength="${maxlength}" rows="4" required></textarea><div class="live-row"><button class="live-primary" type="submit">Submit →</button><button class="live-outline" type="button" id="liveDialogCancel">Cancel</button></div></form></div>`;document.body.style.overflow='hidden';const finish=value=>{host.innerHTML='';document.body.style.overflow='';resolve(value)};host.querySelector('form').addEventListener('submit',e=>{e.preventDefault();e.stopImmediatePropagation();finish($('#liveDialogText').value.trim())});$('#liveDialogCancel').addEventListener('click',()=>finish(null));$('#liveDialogText').focus()})}
  function askReport(name,message=null){return new Promise(resolve=>{const host=$('#modalRoot');host.innerHTML=`<div class="modal-backdrop"><form class="modal live-dialog" role="dialog" aria-modal="true"><div class="modal-icon">⚑</div><h2>Report ${esc(name)}</h2><p class="modal-sub">A moderator can review this report. If you feel unsafe, you can also block this member.</p>${message?`<blockquote class="live-report-preview">${esc(message.slice(0,300))}</blockquote>`:''}<label class="form-label" for="liveReportCategory">Reason</label><select class="form-control" id="liveReportCategory" required>${['Harassment','Scam or spam','Fake profile','Underage concern','Other'].map(v=>`<option>${esc(v)}</option>`).join('')}</select><label class="form-label" for="liveReportReason">What happened?</label><textarea class="form-control" id="liveReportReason" minlength="3" maxlength="500" rows="4" required></textarea><div class="live-row"><button class="live-primary" type="submit">Submit report →</button><button class="live-outline" type="button" id="liveReportCancel">Cancel</button></div></form></div>`;document.body.style.overflow='hidden';const finish=value=>{host.innerHTML='';document.body.style.overflow='';resolve(value)};host.querySelector('form').addEventListener('submit',e=>{e.preventDefault();e.stopImmediatePropagation();const reason=$('#liveReportReason').value.trim();if(reason.length<3)return;finish({category:$('#liveReportCategory').value,reason})});$('#liveReportCancel').addEventListener('click',()=>finish(null));$('#liveReportReason').focus()})}
  function askConfirm(title,description,buttonLabel='Confirm'){return new Promise(resolve=>{const host=$('#modalRoot');host.innerHTML=`<div class="modal-backdrop"><div class="modal live-dialog" role="dialog" aria-modal="true"><div class="modal-icon">⊘</div><h2>${esc(title)}</h2><p class="modal-sub">${esc(description)}</p><div class="live-row"><button class="live-primary" id="liveConfirm">${esc(buttonLabel)}</button><button class="live-outline" id="liveCancel">Cancel</button></div></div></div>`;document.body.style.overflow='hidden';const finish=value=>{host.innerHTML='';document.body.style.overflow='';resolve(value)};$('#liveConfirm').addEventListener('click',()=>finish(true));$('#liveCancel').addEventListener('click',()=>finish(false));$('#liveCancel').focus()})}
  function askDelete(){return new Promise(resolve=>{const host=$('#modalRoot');host.innerHTML=`<div class="modal-backdrop"><form class="modal live-dialog" id="liveDeleteModal" role="dialog" aria-modal="true"><div class="modal-icon">⊘</div><h2>Delete your account?</h2><p class="modal-sub">This permanently removes your profile, photos, links, intros and messages. You cannot undo it.</p><label class="form-label" for="liveDeletePhrase">Type DELETE MY ACCOUNT to confirm</label><input class="form-control" id="liveDeletePhrase" required autocomplete="off"/><div class="live-row"><button class="live-danger" type="submit">Delete account permanently</button><button class="live-outline" type="button" id="liveDeleteCancel">Cancel</button></div></form></div>`;document.body.style.overflow='hidden';const finish=value=>{host.innerHTML='';document.body.style.overflow='';resolve(value)};host.querySelector('form').addEventListener('submit',e=>{e.preventDefault();e.stopImmediatePropagation();if($('#liveDeletePhrase').value.trim()==='DELETE MY ACCOUNT')finish(true);else $('#liveDeletePhrase').setCustomValidity('Type DELETE MY ACCOUNT exactly.');});$('#liveDeletePhrase').addEventListener('input',e=>e.target.setCustomValidity(''));$('#liveDeleteCancel').addEventListener('click',()=>finish(false));$('#liveDeletePhrase').focus()})}
  async function deleteAccount(){if(!state.user||!state.session||!await askDelete())return;if(Date.now()>((state.session.expires_at||0)-60)*1000)await renewSession();const result=await fetch(`${cfg.url}/functions/v1/spark-delete-account`,{method:'POST',headers:{apikey:cfg.publishableKey,Authorization:`Bearer ${state.session.access_token}`,'Content-Type':'application/json'},body:JSON.stringify({confirmation:'DELETE MY ACCOUNT'})});let data;try{data=await result.json()}catch{}if(!result.ok||!data?.deleted)throw Error(data?.error||`Deletion failed (${result.status})`);saveSession(null);state.user=null;state.profile=null;state.profiles=[];state.connections=[];state.unread={};state.latestMessages={};state.messages=[];state.reactions=[];state.chatPrefs=[];state.chatSearch='';state.links=[];state.photos=[];state.blocks=[];state.reports=[];state.suspensions=[];state.preferences=null;state.activityPrivacy=null;state.privateEntitlement=null;state.pausedIds=[];state.isModerator=false;Object.values(state.photoUrls).forEach(url=>URL.revokeObjectURL(url));Object.values(state.mediaUrls).forEach(url=>URL.revokeObjectURL(url));state.mediaUrls={};clearAttachment();state.photoUrls={};state.photoFailed.clear();state.notice='Your account has been deleted.';render()}
  const headers = () => ({apikey:cfg.publishableKey,...(state.session?.access_token?{Authorization:`Bearer ${state.session.access_token}`}:{}),'Content-Type':'application/json'});
  async function renewSession(){if(!state.session?.refresh_token)return;const response=await fetch(`${cfg.url}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:cfg.publishableKey,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:state.session.refresh_token})});const data=await response.json();if(!response.ok)throw new Error(data?.msg||data?.message||'Session expired. Please sign in again.');saveSession({...data,expires_at:Math.floor(Date.now()/1000)+data.expires_in})}
  async function api(path,method='GET',body=null,extra={}) {
    if(state.session && !path.startsWith('/auth/v1/') && Date.now()>((state.session.expires_at||0)-60)*1000)await renewSession();
    const response=await fetch(`${cfg.url}${path}`,{method,headers:{...headers(),...extra},body:body===null?undefined:JSON.stringify(body)});
    const text=await response.text();let data;try{data=text?JSON.parse(text):null}catch{data=text}
    if(!response.ok)throw new Error(data?.msg||data?.message||data?.error_description||data?.error||`Request failed (${response.status})`);
    return data;
  }
  function requireSignedIn(){if(!state.user || !state.profile)throw new Error('Complete your profile to continue.');}
  function otherId(c){return c.requester_id===state.user?.id?c.recipient_id:c.requester_id}
  function person(id){return state.profiles.find(p=>p.id===id)||{id,name:'Member',age:'',city:'',bio:''}}
  function setNav(){document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===state.view));const incoming=state.profile?state.connections.filter(c=>c.recipient_id===state.user.id&&c.status==='pending').length:0;document.querySelectorAll('[data-likes-count]').forEach(el=>{el.textContent=String(incoming);el.hidden=!incoming;el.style.display=incoming?'':'none'});document.querySelectorAll('[data-chat-count]').forEach(el=>{const count=Object.entries(state.unread).reduce((total,[id,n])=>total+(state.chatPrefs.some(p=>p.connection_id===id&&p.muted)?0:n),0);el.textContent=count>99?'99+':String(count);el.hidden=!count;el.style.display=count?'':'none'});document.querySelectorAll('[data-profile-initial]').forEach(el=>el.textContent=state.profile?.name?.[0]?.toUpperCase()||'◉');document.querySelectorAll('[data-profile-name]').forEach(el=>el.textContent=state.profile?`${state.profile.name}, ${state.profile.age}`:'My profile');document.querySelectorAll('[data-profile-city]').forEach(el=>el.textContent=state.profile?.city||'Your city')}
  function shell(content){$('#viewRoot').innerHTML=`<div class="live-wrap">${state.notice?`<p class="live-alert" role="status">${esc(state.notice)}</p>`:''}${content}<footer class="app-footer">Vibely · v0.21.0 · Spark online beta · <span id="sparkCopyright" aria-label="Copyright">©</span></footer></div>`;setNav();window.sparkAdmin?.onRender()}
  function authScreen(){
    const signup=state.authMode==='signup',request=state.authMode==='recovery-request',reset=state.authMode==='recovery-update',confirm=state.authMode==='confirm';
    const title=reset?'Choose a new password':request?'Reset your password':confirm?'Check your inbox':signup?'Create your account':'Welcome back';
    const description=reset?'Use a new password with at least 8 characters.':request?'Enter your account email and we’ll send a reset link.':confirm?'Open the confirmation link in your email. Check spam if it does not arrive.':signup?'Start with an honest hello. You must be 18 or older.':'Sign in to see real people and conversations.';
    const fields=confirm?`<form id="liveResendForm"><label for="liveEmail">Email address</label><input id="liveEmail" type="email" autocomplete="email" value="${esc(state.pendingEmail)}" placeholder="you@example.com" maxlength="254" required/><button class="live-primary" type="submit" ${state.busy?'disabled':''}>${state.busy?'Sending…':'Resend confirmation →'}</button></form>`:reset?`<form id="liveResetForm"><label for="liveNewPassword">New password</label><input id="liveNewPassword" type="password" autocomplete="new-password" minlength="8" required/><label for="liveConfirmPassword">Confirm new password</label><input id="liveConfirmPassword" type="password" autocomplete="new-password" minlength="8" required/><button class="live-primary" type="submit" ${state.busy?'disabled':''}>${state.busy?'Saving…':'Save new password →'}</button></form>`:request?`<form id="liveRecoveryForm"><label for="liveEmail">Email address</label><input id="liveEmail" type="email" autocomplete="email" placeholder="you@example.com" required maxlength="254"/><button class="live-primary" type="submit" ${state.busy?'disabled':''}>${state.busy?'Sending…':'Send reset link →'}</button></form>`:`<form id="liveAuthForm"><label for="liveEmail">Email address</label><input id="liveEmail" type="email" autocomplete="email" placeholder="you@example.com" required maxlength="254"/><label for="livePassword">Password</label><input id="livePassword" type="password" autocomplete="${signup?'new-password':'current-password'}" placeholder="At least 8 characters" required minlength="8"/><button class="live-primary" type="submit" ${state.busy?'disabled':''}>${state.busy?'Please wait…':signup?'Create account':'Sign in'} <span>→</span></button></form>`;
    shell(`<div class="live-auth"><div class="live-auth-art"><div class="live-auth-mark">♥</div><div class="live-auth-copy"><span>MEET AT YOUR OWN PACE</span><h1>A good chat can change everything.</h1><p>Meet as friends. See where the vibe takes you.</p><div class="live-auth-dots"><i></i><i></i><i></i></div></div></div><div class="live-auth-form"><span class="live-kicker">WELCOME TO VIBELY</span><h2>${title}</h2><p>${description}</p>${fields}${reset?'<button class="live-switch" data-live="cancel-reset">Back to sign in</button>':confirm?'<button class="live-switch" data-live="back-to-login">I confirmed my email · Sign in</button>':request?'<button class="live-switch" data-live="back-to-login">Back to sign in</button>':`<button class="live-switch" data-live="toggle-auth">${signup?'Already have an account? Sign in':'New here? Create an account'}</button>${signup?'':'<button class="live-switch live-forgot" data-live="forgot-password">Forgot password?</button><button class="live-switch live-forgot" data-live="confirm-email">Need a new confirmation link?</button>'}`}<small>${confirm?'Confirmation emails can take a few minutes.':request?'If that email has an account, a reset link will arrive.':reset?'The link is valid for a limited time.':'Never share your password or sign-in links.'}</small></div></div>`);
  }
  function setupScreen(){const p=state.profile||{};shell(`<div class="live-page"><div class="live-header"><span class="live-kicker">YOUR PROFILE</span><h1>${state.profile?'Edit your profile':'Let’s get to know you'}</h1><p>Only adults can appear in discovery. Share what feels right.</p></div><form id="liveProfileForm" class="live-form-card"><div class="live-form-grid"><label>Name<input name="name" value="${esc(p.name)}" required minlength="2" maxlength="40" placeholder="Your first name"/></label><label>Age<input name="age" type="number" min="18" max="100" value="${esc(p.age||'')}" required/></label><label>Gender<select name="gender" required>${['Woman','Man','Nonbinary','Prefer not to say'].map(g=>`<option ${p.gender===g?'selected':''}>${g}</option>`).join('')}</select></label><label>City<input name="city" value="${esc(p.city||'Imphal')}" required maxlength="80"/></label></div><label>About you<textarea name="bio" maxlength="500" rows="4" placeholder="A little about your interests and what brings you here">${esc(p.bio)}</textarea></label><label>What are you hoping for?<select name="goal">${['Friends first','Open to a serious relationship','Getting to know people'].map(g=>`<option ${p.goal===g?'selected':''}>${g}</option>`).join('')}</select></label><fieldset class="live-interests"><legend>Pick up to five interests <small>Optional</small></legend><div>${interestOptions.map(v=>`<label><input type="checkbox" name="interest" value="${esc(v)}" ${(p.interests||[]).includes(v)?'checked':''}>${esc(v)}</label>`).join('')}</div></fieldset><label>A conversation starter <small>Optional</small><select name="prompt_question"><option value="">Choose a prompt</option>${promptOptions.map(q=>`<option value="${esc(q)}" ${p.prompt_question===q?'selected':''}>${esc(q)}</option>`).join('')}</select></label><label>Your answer<textarea name="prompt_answer" maxlength="180" rows="2" placeholder="A little something someone can ask you about">${esc(p.prompt_answer||'')}</textarea></label><button class="live-primary" type="submit" ${state.busy?'disabled':''}>${state.busy?'Saving…':'Save profile'} →</button><p class="live-hint">Age is self-declared in this beta. Verification is not available yet.</p></form><button class="live-switch" data-live="sign-out">Sign out</button><button class="live-switch" data-live="delete-account">Delete account</button></div>`)}
  const defaultPreferences={min_age:18,max_age:100,gender_filter:'All',city_only:false,goal_filter:'All'};
  function discoveryCandidates(){if(state.pausedIds.includes(state.user.id))return [];const f=state.preferences||defaultPreferences;const eligible=state.profiles.filter(p=>p.id!==state.user.id&&!state.pausedIds.includes(p.id)&&!state.connections.some(c=>otherId(c)===p.id&&c.status!=='declined')&&p.age>=f.min_age&&p.age<=f.max_age&&(f.gender_filter==='All'||p.gender===f.gender_filter)&&(!f.city_only||p.city.trim().toLocaleLowerCase()===state.profile.city.trim().toLocaleLowerCase())&&(f.goal_filter==='All'||p.goal===f.goal_filter));const day=Math.floor(Date.now()/86400000),rotation=p=>Array.from(p.id+day+state.user.id).reduce((h,c)=>(h*31+c.charCodeAt(0))>>>0,7);const paid=eligible.filter(p=>state.discoveryWeights[p.id]>0).sort((a,b)=>state.discoveryWeights[b.id]-state.discoveryWeights[a.id]||rotation(a)-rotation(b)),basic=eligible.filter(p=>!state.discoveryWeights[p.id]).sort((a,b)=>rotation(a)-rotation(b));const order=[];while(paid.length||basic.length){for(let n=0;n<3&&paid.length;n++)order.push(paid.shift());if(basic.length)order.push(basic.shift());if(!paid.length)order.push(...basic.splice(0))}return order}
  function filtersHtml(){const f=state.preferences||defaultPreferences;return `<details class="live-filters"><summary>Adjust discovery <span>Age ${esc(f.min_age)}–${esc(f.max_age)} · ${esc(f.gender_filter==='All'?'Any gender':f.gender_filter)}</span></summary><form id="liveFiltersForm"><div class="live-form-grid"><label>Minimum age<input type="number" name="min_age" min="18" max="100" value="${esc(f.min_age)}" required></label><label>Maximum age<input type="number" name="max_age" min="18" max="100" value="${esc(f.max_age)}" required></label><label>Show me<select name="gender_filter">${['All','Woman','Man','Nonbinary','Prefer not to say'].map(v=>`<option value="${esc(v)}" ${f.gender_filter===v?'selected':''}>${esc(v==='All'?'Everyone':v)}</option>`).join('')}</select></label><label>Looking for<select name="goal_filter">${['All','Friends first','Open to a serious relationship','Getting to know people'].map(v=>`<option value="${esc(v)}" ${f.goal_filter===v?'selected':''}>${esc(v==='All'?'Any goal':v)}</option>`).join('')}</select></label></div><label class="live-check"><input type="checkbox" name="city_only" ${f.city_only?'checked':''}> Show only people in ${esc(state.profile.city)}</label><button class="live-primary" type="submit">Save preferences →</button></form></details>`}
  function discoverScreen(){const paused=state.pausedIds.includes(state.user.id);const list=discoveryCandidates();if(!list.length){shell(`<div class="live-page"><div class="live-header"><span class="live-kicker">DISCOVER</span><h1>Good things take time.</h1><p>${paused?'Your profile is hidden from new people. Existing matches can still chat.':'No one matches these preferences right now. Try widening your filters or check back later.'}</p></div>${filtersHtml()}<div class="live-empty">✦<h2>${paused?'Discovery paused':'More connections soon'}</h2>${paused?'<button class="live-primary" data-live="toggle-discovery">Resume discovery →</button>':'<p>New adult profiles will appear here when they sign up.</p>'}</div></div>`);return}const p=list[state.selected%list.length];const shown={...p,photo_path:chosenPhoto(p)};shell(`<div class="live-page"><div class="live-header"><span class="live-kicker">A FRIENDLY FIRST HELLO</span><h1>Discover</h1><p>Real people, thoughtful intros, and connections at your pace.</p></div>${filtersHtml()}<div class="live-discover"><article class="live-person"><div class="live-person-art">${photoMarkup(shown)}<span class="live-person-badge">New connection</span></div><div class="live-person-info"><h2>${esc(p.name)}, ${esc(p.age)}</h2><p>⌖ ${esc(p.city)} · ${esc(p.goal)}</p><blockquote>${esc(p.bio||'Say hello and start a conversation.')}</blockquote>${personalityHtml(p)}${galleryThumbsHtml(p)}${socialLinksHtml(p.id)}<div class="live-person-actions"><button data-live="skip" aria-label="Next profile">×</button><button class="live-heart" data-live="intro" aria-label="Send intro">♥</button><button data-live="block" data-id="${esc(p.id)}" aria-label="Block profile">⊘</button></div><button class="live-primary" data-live="intro">Send a friendly intro →</button><button class="live-text" data-live="report" data-id="${esc(p.id)}">Report this profile</button></div></article><aside class="live-side"><span>✦</span><h3>Start with a real conversation.</h3><p>A short note gives someone a reason to say hello. Chat opens only after they accept.</p><div>✓ Your city, not your exact location<br/>✓ Block or report whenever you need</div></aside></div></div>`)}
  function likesScreen(){const incoming=state.connections.filter(c=>c.recipient_id===state.user.id&&c.status==='pending');const sent=state.connections.filter(c=>c.requester_id===state.user.id&&c.status==='pending');shell(`<div class="live-page"><div class="live-header"><span class="live-kicker">A LITTLE SPARK</span><h1>Likes & intros</h1><p>You choose who you’d like to talk with.</p></div><div class="live-columns"><section class="live-list"><h2>Received <span>${incoming.length}</span></h2>${incoming.length?incoming.map(c=>`<article class="live-item"><span class="live-item-avatar">${esc(person(c.requester_id).name[0])}</span><div><h3>${esc(person(c.requester_id).name)}</h3><p>${esc(c.intro)}</p><div class="live-row"><button data-live="accept" data-id="${esc(c.id)}">Accept & chat</button><button data-live="decline" data-id="${esc(c.id)}">Pass</button><button data-live="block" data-id="${esc(c.requester_id)}">Block</button></div></div></article>`).join(''):'<p class="live-muted">No new intros yet.</p>'}</section><section class="live-list"><h2>Sent <span>${sent.length}</span></h2>${sent.length?sent.map(c=>`<article class="live-item"><span class="live-item-avatar">${esc(person(c.recipient_id).name[0])}</span><div><h3>${esc(person(c.recipient_id).name)}</h3><p>${esc(c.intro)}</p><small>Waiting for their reply</small></div></article>`).join(''):'<p class="live-muted">You haven’t sent an intro yet.</p>'}</section></div></div>`)}
  function messageText(value){
    return String(value||'').split(/(https:\/\/[^\s<>]+)/g).map(part=>{
      if(!part.startsWith('https://'))return esc(part);
      try{const url=new URL(part);return url.protocol==='https:'?`<a href="${esc(url.href)}" target="_blank" rel="noopener noreferrer">${esc(part)}</a>`:esc(part)}catch{return esc(part)}
    }).join('');
  }
  function attachmentMarkup(m){
    const url=state.mediaUrls[m.attachment_path];
    if(!url){ensureAttachment(m);return '<span class="live-media-loading">Loading attachment…</span>'}
    return m.attachment_kind==='image'
      ?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer" aria-label="Open image"><img src="${esc(url)}" alt="Photo attachment" loading="lazy" class="live-chat-image"></a>`
      :`<audio controls preload="metadata" src="${esc(url)}" aria-label="Voice note"></audio>`;
  }
  function ensureAttachment(m){
    if(!m.attachment_path||state.mediaUrls[m.attachment_path]||state.mediaLoading.has(m.attachment_path))return;
    state.mediaLoading.add(m.attachment_path);
    storageRequest(`authenticated/spark-chat-media/${storagePath(m.attachment_path)}`).then(r=>r.blob()).then(blob=>{
      state.mediaUrls[m.attachment_path]=URL.createObjectURL(blob);
      const el=document.getElementById(`liveMedia-${m.id}`);
      if(el)el.innerHTML=attachmentMarkup(m);
    }).catch(()=>{const el=document.getElementById(`liveMedia-${m.id}`);if(el)el.textContent='Attachment unavailable.'}).finally(()=>state.mediaLoading.delete(m.attachment_path));
  }
  function messagesHtml(){return state.messages.map(m=>{
    const mine=m.sender_id===state.user.id;
    return `<div class="live-message-row ${mine?'mine':'theirs'}"><span class="live-message-avatar" aria-hidden="true">${mine?'You':esc(person(m.sender_id).name[0])}</span><div class="live-message ${mine?'mine':'theirs'}"><span class="live-message-owner">${mine?'You':esc(person(m.sender_id).name)}</span>${m.attachment_path?`<div class="live-media" id="liveMedia-${esc(m.id)}">${attachmentMarkup(m)}</div>`:''}${m.body&&!m.attachment_path?`<p>${messageText(m.body)}</p>`:m.attachment_path&&m.body&&!['Photo','Voice note'].includes(m.body)?`<p>${messageText(m.body)}</p>`:''}<small>${esc(new Date(m.created_at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}))}${mine?(m.read_at?' · ✓✓ Seen':' · ✓ Sent'):''}</small><div class="live-reactions">${state.reactions.filter(r=>r.message_id===m.id).map(r=>`<span title="${r.user_id===state.user.id?'Your reaction':'Their reaction'}">${esc(r.emoji)}</span>`).join('')}<button data-live="reaction-picker" data-id="${esc(m.id)}" aria-label="React to message" title="React">♡</button></div>${!mine?`<button class="live-message-report" data-live="report-message" data-id="${esc(m.id)}" aria-label="Report this message">Report</button>`:''}</div></div>`
  }).join('')}
  function chatPref(id){return state.chatPrefs.find(p=>p.connection_id===id)||{pinned:false,muted:false}}
  function sortedChats(){return state.connections.filter(c=>c.status==='accepted').sort((a,b)=>Number(chatPref(b.id).pinned)-Number(chatPref(a.id).pinned)||new Date(state.latestMessages[b.id]?.created_at||b.created_at||0)-new Date(state.latestMessages[a.id]?.created_at||a.created_at||0))}
  function chatListHtml(accepted,activeId){return accepted.filter(c=>!state.chatSearch||person(otherId(c)).name.toLocaleLowerCase().includes(state.chatSearch)||String(state.latestMessages[c.id]?.body||'').toLocaleLowerCase().includes(state.chatSearch)).map(c=>{const p=person(otherId(c)),latest=state.latestMessages[c.id],preview=latest?`${latest.sender_id===state.user.id?'You: ':''}${latest.body}`:`Intro: ${c.intro||'Say hello first'}`,time=latest?.created_at||c.created_at,when=time?new Date(time):null,shortTime=when&&!Number.isNaN(when.valueOf())?(when.toDateString()===new Date().toDateString()?when.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}):when.toLocaleDateString([],{month:'short',day:'numeric'})):'';return `<button data-live="select-chat" data-id="${esc(c.id)}" class="${c.id===activeId?'active':''}" aria-label="Chat with ${esc(p.name)}${state.unread[c.id]?`, ${state.unread[c.id]} unread`:''}"><span class="live-item-avatar">${esc(p.name[0])}</span><span class="live-chat-meta"><strong>${chatPref(c.id).pinned?'📌 ':''}${esc(p.name)}${chatPref(c.id).muted?' · Muted':''}</strong><small>${esc(preview)}</small></span><span class="live-chat-trailing"><time>${esc(shortTime)}</time>${state.unread[c.id]?`<span class="live-chat-unread" aria-label="${state.unread[c.id]} unread messages">${state.unread[c.id]>99?'99+':state.unread[c.id]}</span>`:''}</span></button>`}).join('')}
  function updateChatList(){const list=$('#liveChatList');if(list)list.innerHTML=chatListHtml(sortedChats(),state.activeChat)}
  function pendingMarkup(){const p=state.pendingAttachment;return p?`<div class="live-attachment-preview"><span>${p.kind==='image'?'📷 Photo':'🎙 Voice note'} · ${esc((p.blob.size/1048576).toFixed(2))} MB</span>${p.previewUrl?(p.kind==='audio'?`<audio controls src="${esc(p.previewUrl)}"></audio>`:`<img src="${esc(p.previewUrl)}" alt="Selected photo preview">`):''}<button type="button" data-live="remove-attachment" aria-label="Remove attachment">×</button></div>`:''}
  function chatsScreen(){const accepted=sortedChats();if(!accepted.length){shell(`<div class="live-page"><div class="live-header"><span class="live-kicker">CONVERSATIONS</span><h1>Chats</h1><p>When you both say hello, your conversation begins here.</p></div><div class="live-empty">♡<h2>No matches yet</h2><button class="live-primary" data-live="discover">Discover people →</button></div></div>`);return}let c=accepted.find(x=>x.id===state.activeChat)||accepted[0];state.activeChat=c.id;const p=person(otherId(c));shell(`<div class="live-page"><div class="live-header"><span class="live-kicker">ONE MESSAGE AT A TIME</span><h1>Chats</h1></div><div class="live-chat"><aside class="live-chat-sidebar"><label class="live-chat-search" for="liveChatSearch">Search chats<input id="liveChatSearch" type="search" value="${esc(state.chatSearch)}" placeholder="Name or recent message"></label><div class="live-chat-list" id="liveChatList" aria-label="Conversations">${chatListHtml(accepted,c.id)}</div></aside><section class="live-chat-room"><header><span class="live-item-avatar">${esc(p.name[0])}</span><div><strong>${esc(p.name)}</strong><small>Private matched conversation · You are ${esc(state.profile.name)}</small></div><button class="live-text" data-live="pin-chat" data-id="${esc(c.id)}">${chatPref(c.id).pinned?'Unpin':'Pin'}</button><button class="live-text" data-live="mute-chat" data-id="${esc(c.id)}">${chatPref(c.id).muted?'Unmute':'Mute'}</button><button class="live-text" data-live="block" data-id="${esc(p.id)}">Block</button><button class="live-text" data-live="report" data-id="${esc(p.id)}">Report</button></header>${socialLinksHtml(p.id)}<div class="live-chat-messages" id="liveMessages" role="log" aria-label="Conversation with ${esc(p.name)}">${messagesHtml()}</div><form id="liveMessageForm"><div id="liveComposerPreview">${pendingMarkup()}</div><div class="live-composer-row"><button class="live-tool" type="button" data-live="pick-photo" aria-label="Attach a photo" title="Attach a photo">＋</button><button class="live-tool" type="button" data-live="take-photo" aria-label="Take a photo" title="Take a photo">📷</button><input id="livePhotoAttachment" type="file" accept="image/jpeg,image/png,image/webp" hidden><input id="liveCameraAttachment" type="file" accept="image/*" capture="environment" hidden><div class="live-composer-input"><input name="body" maxlength="1000" autocomplete="off" placeholder="Write a kind message…" aria-label="Message"><button class="live-tool" type="button" data-live="emoji-picker" aria-label="Choose emoji" title="Emoji">☺</button><div class="live-emoji-picker" id="liveEmojiPicker" hidden>${['😊','❤️','😂','🥰','👍','✨','🎉','👋','🌷','☕','🙏','😍','😄','💜','🔥','🌻'].map(e=>`<button type="button" data-live="insert-emoji" data-id="${e}" aria-label="Insert ${e}">${e}</button>`).join('')}</div></div><button class="live-tool live-mic" type="button" data-live="record-audio" aria-label="Record voice note" title="Record voice note">🎙</button><button class="live-primary" type="submit">Send →</button></div><small class="live-composer-hint" id="liveRecordStatus">Photos and voice notes up to 5 MB. Tap mic to record, tap again to preview.</small></form></section></div></div>`);$('#liveMessages').scrollTop=$('#liveMessages').scrollHeight}
  function clearAttachment(){if(state.pendingAttachment?.previewUrl)URL.revokeObjectURL(state.pendingAttachment.previewUrl);state.pendingAttachment=null;const preview=$('#liveComposerPreview');if(preview)preview.innerHTML=''}
  async function chooseAttachment(file){if(!file)return;try{
    let kind,blob,mime,ext;
    if(['image/jpeg','image/png','image/webp'].includes(file.type)){kind='image';blob=await photoBlob(file);mime='image/webp';ext='webp'}
    else if(['audio/webm','audio/ogg','audio/mp4','audio/mpeg'].includes(file.type)){kind='audio';blob=file;mime=file.type;ext=({'audio/webm':'webm','audio/ogg':'ogg','audio/mp4':'m4a','audio/mpeg':'mp3'})[mime]}
    else throw Error('Choose a JPG, PNG, WebP or supported audio file.');
    if(blob.size>5242880)throw Error('The attachment must be 5 MB or smaller.');
    clearAttachment();state.pendingAttachment={kind,blob,mime,ext,connectionId:state.activeChat,previewUrl:URL.createObjectURL(blob)};
    $('#liveComposerPreview').innerHTML=pendingMarkup();
  }catch(error){notify(error.message)}}
  async function recordAudio(){if(state.recorder){if(state.recorder.state==='recording')state.recorder.stop();return}
    if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return notify('Voice recording is not available in this browser.');
    try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=['audio/webm','audio/mp4','audio/ogg'].find(type=>MediaRecorder.isTypeSupported(type));if(!mime){stream.getTracks().forEach(t=>t.stop());throw Error('This browser cannot encode a supported voice note.')}
      const recorder=new MediaRecorder(stream,{mimeType:mime});state.recordingStream=stream;state.recorder=recorder;state.recordChunks=[];state.recordStarted=Date.now();
      recorder.ondataavailable=e=>{if(e.data.size)state.recordChunks.push(e.data);if(state.recordChunks.reduce((n,b)=>n+b.size,0)>5242880)recorder.stop()};
      recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());state.recorder=null;state.recordingStream=null;const blob=new Blob(state.recordChunks,{type:mime});state.recordChunks=[];const status=$('#liveRecordStatus');if(status)status.textContent='Photos and voice notes up to 5 MB. Tap mic to record, tap again to preview.';const mic=$('.live-mic');mic?.classList.remove('recording');if(blob.size>5242880)return notify('Voice note exceeded 5 MB. Record a shorter note.');if(blob.size)chooseAttachment(new File([blob],'voice-note',{type:mime}))};
      recorder.start(1000);$('#liveRecordStatus').textContent='Recording… tap mic again to stop and preview.';$('.live-mic').classList.add('recording');
    }catch(error){notify(error.message||'Microphone access was denied.')}}
  async function sendMessage(form){const input=form.querySelector('input[name=body]'),body=input.value.trim(),attachment=state.pendingAttachment;
    if(state.sendingMessage||(!body&&!attachment))return;
    if(attachment&&attachment.connectionId!==state.activeChat)return notify('Choose the attachment again for this conversation.');
    state.sendingMessage=true;const button=form.querySelector('button[type=submit]');button.disabled=true;button.textContent='Sending…';let path=null;
    try{const payload={connection_id:state.activeChat,sender_id:state.user.id,body:body||(attachment?.kind==='image'?'Photo':'Voice note')};
      if(attachment){path=`${state.user.id}/${state.activeChat}/${crypto.randomUUID()}.${attachment.ext}`;await storageRequest(`spark-chat-media/${storagePath(path)}`,'POST',attachment.blob,attachment.mime);Object.assign(payload,{attachment_path:path,attachment_kind:attachment.kind,attachment_mime:attachment.mime})}
      await api('/rest/v1/spark_messages','POST',payload);
      clearAttachment();input.value='';await loadChatSummaries();await loadMessages();const box=$('#liveMessages');if(box){box.innerHTML=messagesHtml();box.scrollTop=box.scrollHeight}
    }catch(error){if(path)storageRequest('spark-chat-media','DELETE',JSON.stringify({prefixes:[path]}),'application/json').catch(()=>{});notify(error.message)}finally{state.sendingMessage=false;if(button.isConnected){button.disabled=false;button.textContent='Send →'}}
  }

  function socialEditorHtml(){const own=socialLinksFor(state.user.id);return `<section class="live-social-editor"><div class="live-social-heading"><span class="live-kicker">YOUR CONTROL</span><h2>Social profiles</h2><p>Add a link if you want people to learn more about you. Each link starts hidden. You can change or remove it anytime.</p></div><form id="liveSocialForm" class="live-social-form"><label>Platform<select name="platform" id="liveSocialPlatform">${platforms.map(platform=>`<option>${platform}</option>`).join('')}</select></label><label>Profile link<input name="url" type="url" id="liveSocialUrl" placeholder="https://instagram.com/yourname" maxlength="500" required autocomplete="url"/></label><label>Who can see it?<select name="visibility" id="liveSocialVisibility"><option value="hidden">Hidden (only me)</option><option value="matches">Matches only</option><option value="members">All signed-in members</option></select></label><button class="live-primary" type="submit">Save link →</button></form><p class="live-social-disclaimer">A link you enter is self-added, not proof of identity. Someone who has seen it may keep a copy after you hide it.</p>${own.length?`<div class="live-social-list">${own.map(link=>`<div class="live-social-item"><div><strong>${esc(link.platform)}</strong><span>${esc(visibilityLabels[link.visibility]||'Hidden')}</span><small>${esc(link.url)}</small></div><div class="live-row"><button class="live-outline" data-live="edit-social" data-id="${esc(link.id)}">Edit</button><button class="live-outline" data-live="remove-social" data-id="${esc(link.id)}">Remove</button></div></div>`).join('')}</div>`:'<p class="live-muted">No social links saved yet.</p>'}</section>`}
  function privateActivityActive(){return Boolean(state.activityPrivacy?.hide_activity&&state.privateEntitlement&&new Date(state.privateEntitlement.expires_at).getTime()>Date.now())}
  function privateActivityCard(){const entitled=Boolean(state.privateEntitlement&&new Date(state.privateEntitlement.expires_at).getTime()>Date.now()),active=privateActivityActive();return `<section class="live-private-card"><span class="live-private-badge">✦ TOP ADD-ON</span><h3>Private Activity</h3><p>Read messages without sharing a new Seen receipt. Your own unread badges still clear. You can still see receipts from people who share them.</p><div class="live-private-state"><span>${active?'On · Future reads stay private':entitled?'Off · Read receipts are shared':'Locked · Purchase coming soon'}</span>${entitled?`<button class="live-outline" data-live="toggle-private-activity" aria-pressed="${active}">${active?'Turn off':'Turn on'}</button>`:`<button class="live-outline" data-live="premium">Explore add-on</button>`}</div><small>Earlier Seen receipts remain visible. Online status and last seen are not shown in this beta. Billing is not active yet.</small></section>`}
  async function togglePrivateActivity(){if(!state.privateEntitlement||new Date(state.privateEntitlement.expires_at).getTime()<=Date.now()){state.view='premium';return render()}
    const hide_activity=!privateActivityActive(),path='/rest/v1/spark_activity_preferences';
    try{const rows=state.activityPrivacy?await api(`${path}?owner_id=eq.${state.user.id}`,'PATCH',{hide_activity},{Prefer:'return=representation'}):await api(path,'POST',{owner_id:state.user.id,hide_activity},{Prefer:'return=representation'});
      if(!rows?.length)throw Error('Setting was not saved.');state.activityPrivacy=rows[0];state.notice=hide_activity?'Private Activity is on for future reads.':'Read receipts are on for new messages.';render()
    }catch(error){notify(error.message)}}
  function profileScreen(){const p=state.profile;shell(`<div class="live-page"><div class="live-header"><span class="live-kicker">YOUR SPACE</span><h1>My profile</h1><p>Choose what you share with the people you meet.</p></div><div class="live-profile"><div class="live-profile-banner">${photoMarkup(p)}</div><h2>${esc(p.name)}, ${esc(p.age)}</h2><p>⌖ ${esc(p.city)} · ${esc(p.goal)}</p><blockquote>${esc(p.bio||'Tell people a little about yourself.')}</blockquote>${personalityHtml(p)}<div class="live-row"><button class="live-primary" data-live="edit-profile">Edit profile</button><button class="live-outline" data-live="safety">Safety & privacy</button>${state.isModerator?'<button class="live-outline" data-live="moderation">Review reports</button>':''}<button class="live-outline" data-live="sign-out">Sign out</button></div>${privateActivityCard()}<section id="ownerMemberNotices" class="live-private-card" aria-label="Spark updates"></section><small>Verification and payments are not active in this beta.</small></div>${photoGalleryHtml(p)}${socialEditorHtml()}</div>`)}
  function safetyScreen(){const matches=state.connections.filter(c=>c.status==='accepted');shell(`<div class="live-page"><div class="live-header"><span class="live-kicker">STAY IN CONTROL</span><h1>Safety & privacy</h1><p>Manage who can contact you. A blocked member cannot see your profile or photos.</p></div><div class="live-columns"><section class="live-list"><h2>Blocked members <span>${state.blocks.filter(b=>b.blocker_id===state.user.id).length}</span></h2>${state.blocks.filter(b=>b.blocker_id===state.user.id).map(b=>`<article class="live-item"><span class="live-item-avatar">⊘</span><div><h3>${esc(b.blocked_name)}</h3><p>Blocked from your profile and messages.</p><button class="live-outline" data-live="unblock" data-id="${esc(b.blocked_id)}">Unblock</button></div></article>`).join('')||'<p class="live-muted">You have not blocked anyone.</p>'}</section><section class="live-list"><h2>Matches <span>${matches.length}</span></h2>${matches.map(c=>`<article class="live-item"><span class="live-item-avatar">♡</span><div><h3>${esc(person(otherId(c)).name)}</h3><p>You can end this match at any time.</p><button class="live-outline" data-live="end-match" data-id="${esc(c.id)}">End match</button></div></article>`).join('')||'<p class="live-muted">No active matches yet.</p>'}</section></div><section class="live-visibility-zone"><h2>Discovery visibility</h2><p>${state.pausedIds.includes(state.user.id)?'Your profile is hidden from new people. Existing matches can still chat.':'Your profile can appear to other signed-in members.'}</p><button class="live-outline" data-live="toggle-discovery">${state.pausedIds.includes(state.user.id)?'Resume discovery':'Pause discovery'}</button></section><section class="live-delete-zone"><h2>Delete your account</h2><p>Remove your Spark account and its data permanently.</p><button class="live-danger" data-live="delete-account">Delete account</button></section><button class="live-switch" data-live="profile">← Back to profile</button></div>`)}
  function pausedScreen(){shell(`<div class="live-page"><div class="live-header"><span class="live-kicker">ACCOUNT REVIEW</span><h1>Your profile is paused</h1><p>Your profile and photos are hidden while the Spark team reviews your account. Matching and chat are unavailable during this review.</p></div><div class="live-empty">⊘<h2>Account under review</h2><p>Sign out and contact the Spark team if you believe this is a mistake.</p><button class="live-outline" data-live="sign-out">Sign out</button></div></div>`)}
  function moderationScreen(){if(!state.isModerator){state.view='profile';return profileScreen()}const reports=[...state.reports].sort((a,b)=>(a.status==='pending'?0:1)-(b.status==='pending'?0:1)||new Date(b.created_at)-new Date(a.created_at));shell(`<div class="live-page"><div class="live-header"><span class="live-kicker">SPARK SAFETY</span><h1>Review reports</h1><p>Investigate reports before acting. Pausing a profile hides it and stops its chats until restored.</p></div><div class="live-moderation">${reports.map(report=>{const paused=state.suspensions.includes(report.reported_id),p=person(report.reported_id);return `<article class="live-report"><div class="live-report-top"><strong>${esc(p.name)}</strong><span class="live-status ${esc(report.status)}">${esc(report.status)}</span><span class="live-status">${esc(report.category||'Other')}</span>${paused?'<span class="live-status paused">Profile paused</span>':''}</div><small>Reported ${esc(new Date(report.created_at).toLocaleString())} · Account ${esc(report.reported_id.slice(0,8))}</small><p>${esc(report.reason)}</p>${report.message_excerpt?`<blockquote class="live-report-preview"><strong>Reported message</strong><br>${esc(report.message_excerpt)}</blockquote>`:''}${report.media_path?`<div class="live-report-media"><strong>Reported ${esc(report.media_kind||'media')}</strong><div class="live-media" id="liveMedia-${esc(report.id)}">${attachmentMarkup({id:report.id,attachment_path:report.media_path,attachment_kind:report.media_kind})}</div></div>`:''}<div class="live-row">${report.status==='pending'?`<button class="live-outline" data-live="review-report" data-id="${esc(report.id)}">Mark reviewed</button><button class="live-outline" data-live="dismiss-report" data-id="${esc(report.id)}">Dismiss report</button>`:''}${paused?`<button class="live-outline" data-live="restore-member" data-id="${esc(report.reported_id)}">Restore profile</button>`:`<button class="live-danger" data-live="pause-member" data-id="${esc(report.reported_id)}">Pause profile</button>`}</div></article>`}).join('')||'<div class="live-empty">✓<h2>No reports yet</h2><p>New member reports will appear here.</p></div>'}</div><button class="live-switch" data-live="profile">← Back to profile</button></div>`)}
  async function triageReport(id,status){if(!state.isModerator)return;const report=state.reports.find(r=>r.id===id);if(!report||report.status!=='pending')return;const rows=await api(`/rest/v1/spark_reports?id=eq.${encodeURIComponent(id)}&status=eq.pending`,'PATCH',{status,reviewed_by:state.user.id,reviewed_at:new Date().toISOString()},{Prefer:'return=representation'});if(!rows.length)throw Error('Report was already updated.');state.notice=status==='dismissed'?'Report dismissed.':'Report marked reviewed.';await load()}
  async function pauseMember(id){if(!state.isModerator||id===state.user.id||state.suspensions.includes(id))return;if(!await askConfirm('Pause this profile?','The member will disappear from discovery and chats will stop for both people. Review the report before proceeding.','Pause profile'))return;await api('/rest/v1/spark_suspended_profiles','POST',{user_id:id,moderator_id:state.user.id});state.notice='Profile paused. Review and resolve the related report.';await load()}
  async function restoreMember(id){if(!state.isModerator||!state.suspensions.includes(id))return;if(!await askConfirm('Restore this profile?','The member will be visible again and previous matches can chat.','Restore profile'))return;await api(`/rest/v1/spark_suspended_profiles?user_id=eq.${encodeURIComponent(id)}`,'DELETE');state.notice='Profile restored.';await load()}
  function premiumScreen(){shell(`<div class="live-page"><div class="live-header"><span class="live-kicker">VIBELY PREMIUM</span><h1>Make room for more.</h1><p>Optional upgrades are being prepared. No payment is being collected.</p></div><section class="live-premium-hero"><span class="live-private-badge">✦ TOP ADD-ON</span><h2>Private Activity</h2><p>Keep future chat reads private while your own unread counts work normally. You can turn it on or off from My profile after an add-on is active.</p><strong>${privateActivityActive()?'Active':state.privateEntitlement&&new Date(state.privateEntitlement.expires_at).getTime()>Date.now()?'Ready to enable':'Purchase opening later'}</strong><small>Past Seen receipts cannot be withdrawn. The add-on is separate from future Vibely Plus plans; pricing and checkout are not live yet.</small><button class="live-outline" data-live="profile">View profile setting</button></section><div id="liveDynamicPlans"></div><div class="live-empty">✦<h2>More ways to connect are on the way.</h2><p>Free discovery, intros and matched chat are available now.</p></div></div>`)}
  function render(){if(!$('#viewRoot'))return;if(state.authMode==='recovery-update'||!state.user)return authScreen();if(!state.profile)return setupScreen();if(state.suspensions.includes(state.user.id)&&state.view!=='moderation')return pausedScreen();({discover:discoverScreen,likes:likesScreen,chats:chatsScreen,profile:profileScreen,safety:safetyScreen,moderation:moderationScreen,premium:premiumScreen}[state.view]||discoverScreen)()}
  async function load(){requireSignedIn();const [profiles,connections,links,photos,blocks,moderators,suspensions,preferences,pauses]=await Promise.all([api('/rest/v1/spark_profiles?select=id,name,age,gender,city,bio,goal,photo_path,interests,prompt_question,prompt_answer&order=created_at.desc&limit=200'),api('/rest/v1/spark_connections?select=*&order=created_at.desc&limit=200'),api('/rest/v1/spark_social_links?select=id,owner_id,platform,url,visibility&order=platform.asc&limit=500'),api('/rest/v1/spark_profile_photos?select=id,owner_id,path,slot&order=slot.asc&limit=800'),api('/rest/v1/spark_blocks?select=blocker_id,blocked_id,blocked_name&limit=500'),api(`/rest/v1/spark_moderators?select=user_id&user_id=eq.${state.user.id}`),api('/rest/v1/spark_suspended_profiles?select=user_id&limit=1000'),api(`/rest/v1/spark_discovery_preferences?select=owner_id,min_age,max_age,gender_filter,city_only,goal_filter&owner_id=eq.${state.user.id}`),api('/rest/v1/spark_discovery_pauses?select=user_id&limit=1000')]);const [activityRows,entitlementRows]=await Promise.all([api(`/rest/v1/spark_activity_preferences?select=owner_id,hide_activity,changed_at&owner_id=eq.${state.user.id}`),api(`/rest/v1/spark_private_activity_entitlements?select=user_id,expires_at&user_id=eq.${state.user.id}`)]);state.activityPrivacy=activityRows[0]||null;state.privateEntitlement=entitlementRows[0]||null;state.preferences=preferences[0]||{...defaultPreferences};state.pausedIds=pauses.map(p=>p.user_id);state.profiles=profiles;const weights=await api('/rest/v1/rpc/spark_discovery_weights','POST',{});state.discoveryWeights=Object.fromEntries(weights.map(w=>[w.profile_id,w.boost]));state.connections=connections;state.chatPrefs=await api(`/rest/v1/spark_chat_preferences?select=owner_id,connection_id,pinned,muted&owner_id=eq.${state.user.id}`); state.links=links;state.photos=photos;state.blocks=blocks;state.isModerator=moderators.some(m=>m.user_id===state.user.id);state.suspensions=suspensions.map(s=>s.user_id);state.reports=state.isModerator?await api('/rest/v1/spark_reports?select=id,reporter_id,reported_id,reason,category,message_excerpt,media_path,media_kind,created_at,status&order=created_at.desc&limit=200'):[];await loadUnread();if(state.view==='chats'){await loadChatSummaries();await loadMessages()}render()}
  async function loadUnread(){if(!state.user||!state.profile)return;
    const [rows,views]=await Promise.all([api(`/rest/v1/spark_messages?select=id,connection_id&sender_id=neq.${state.user.id}&read_at=is.null&limit=1000`),api(`/rest/v1/spark_message_views?select=message_id&viewer_id=eq.${state.user.id}&limit=1000`)]);
    const seen=new Set(views.map(v=>v.message_id));state.unread={};rows.forEach(m=>{if(!seen.has(m.id))state.unread[m.connection_id]=(state.unread[m.connection_id]||0)+1});setNav();updateChatList()
  }
  async function loadChatSummaries(){const rows=await api('/rest/v1/spark_messages?select=connection_id,sender_id,body,created_at&order=created_at.desc&limit=500');state.latestMessages={};rows.forEach(m=>{if(!state.latestMessages[m.connection_id])state.latestMessages[m.connection_id]=m});updateChatList()}
  async function loadMessages(){const accepted=sortedChats();const id=accepted.find(c=>c.id===state.activeChat)?.id||accepted[0]?.id;if(!id){state.activeChat=null;state.messages=[];return}state.activeChat=id;
    const [messages,views,reactions]=await Promise.all([api(`/rest/v1/spark_messages?select=id,connection_id,sender_id,body,attachment_path,attachment_kind,attachment_mime,created_at,read_at&connection_id=eq.${encodeURIComponent(id)}&order=created_at.asc&limit=200`),api(`/rest/v1/spark_message_views?select=message_id&viewer_id=eq.${state.user.id}&connection_id=eq.${encodeURIComponent(id)}&limit=1000`),api(`/rest/v1/spark_message_reactions?select=message_id,connection_id,user_id,emoji&connection_id=eq.${encodeURIComponent(id)}&limit=1000`)]);
    state.messages=messages;state.reactions=reactions;if(state.view!=='chats'||document.hidden)return;
    const seen=new Set(views.map(v=>v.message_id));const fresh=messages.filter(m=>m.sender_id!==state.user.id&&!m.read_at&&!seen.has(m.id));
    if(!fresh.length)return;
    if(!privateActivityActive()){
      const ids=fresh.map(m=>m.id).join(',');
      try{await api(`/rest/v1/spark_messages?id=in.(${ids})&connection_id=eq.${encodeURIComponent(id)}&sender_id=neq.${state.user.id}&read_at=is.null`,'PATCH',{read_at:new Date().toISOString()});fresh.forEach(m=>m.read_at=new Date().toISOString())}
      catch(error){if(!/read receipts are hidden/i.test(error.message))throw error}
    }
    await api('/rest/v1/spark_message_views','POST',fresh.map(m=>({message_id:m.id,connection_id:id,viewer_id:state.user.id})),{Prefer:'resolution=ignore-duplicates'});
    await loadUnread()
  }

  async function restore(){
    const fragment=new URLSearchParams(location.hash.slice(1));
    if(fragment.has('access_token')||fragment.has('error')||fragment.has('error_description')){
      history.replaceState(null,'',location.pathname+location.search);
      if(fragment.has('error')){state.authMode='login';state.notice=fragment.get('error_description')||'This email link has expired. Request another link.';return render()}
      const access_token=fragment.get('access_token'),refresh_token=fragment.get('refresh_token'),expires_in=Number(fragment.get('expires_in'));
      if(!access_token||!refresh_token||!Number.isFinite(expires_in)||expires_in<=0){state.notice='This email link is invalid. Request another link.';return render()}
      saveSession(null);
      state.session={access_token,refresh_token,expires_in,expires_at:Math.floor(Date.now()/1000)+expires_in};
      if(fragment.get('type')==='recovery'){
        state.authMode='recovery-update';
        try{state.user=await api('/auth/v1/user');return render()}catch{state.session=null;state.user=null;state.authMode='login';state.notice='This reset link has expired. Request another link.';return render()}
      }
      saveSession(state.session);state.notice='Your email is confirmed. Complete your profile or continue exploring.';
    }else{try{state.session=JSON.parse(localStorage.getItem('spark-live-session')||'null')}catch{saveSession(null)}}
    if(!state.session)return render();
    try{if(Date.now()>((state.session.expires_at||0)-60)*1000)await renewSession();state.user=await api('/auth/v1/user');const profiles=await api(`/rest/v1/spark_profiles?select=*&id=eq.${state.user.id}`);state.profile=profiles[0]||null;if(state.profile)await load();else render()}catch(error){saveSession(null);state.user=null;state.profile=null;notify(`Please sign in again. ${error.message}`)}
  }
  const authReturnUrl=()=>location.origin+location.pathname;
  async function requestRecovery(email){if(state.busy)return;state.busy=true;state.notice='';render();try{await api(`/auth/v1/recover?redirect_to=${encodeURIComponent(authReturnUrl())}`,'POST',{email});state.busy=false;notify('If that email has an account, a reset link is on its way. Check your inbox.')}catch(error){state.busy=false;notify(error.message)}}
  async function updatePassword(password,confirmation){if(password!==confirmation)return notify('Passwords do not match.');if(password.length<8)return notify('Use at least 8 characters.');if(state.busy)return;state.busy=true;state.notice='';render();try{await api('/auth/v1/user','PUT',{password});try{await api('/auth/v1/logout?scope=local','POST',{})}catch{}saveSession(null);state.user=null;state.profile=null;state.authMode='login';state.busy=false;notify('Password changed. Sign in with your new password.')}catch(error){state.busy=false;notify(error.message)}}

  async function resendConfirmation(email){if(state.busy)return;if(Date.now()<state.resendAvailableAt)return notify('Please wait about a minute before requesting another email.');state.busy=true;state.pendingEmail=email;state.notice='';render();try{await api(`/auth/v1/resend?redirect_to=${encodeURIComponent(authReturnUrl())}`,'POST',{email,type:'signup'});state.resendAvailableAt=Date.now()+60000;state.busy=false;notify('If this account needs confirmation, a new link is on its way. Check your inbox and spam folder.')}catch(error){state.busy=false;notify(error.message)}}
  async function submitAuth(form){if(state.busy)return;const email=form.email.value.trim(),password=form.password.value,signup=state.authMode==='signup';state.busy=true;state.notice='';render();try{const result=await api(signup?`/auth/v1/signup?redirect_to=${encodeURIComponent(authReturnUrl())}`:'/auth/v1/token?grant_type=password','POST',{email,password});if(!result.access_token){state.busy=false;state.pendingEmail=email;state.authMode='confirm';return notify('We sent a confirmation link if this email needs one.')}saveSession({...result,expires_at:Math.floor(Date.now()/1000)+result.expires_in});state.user=result.user;const profiles=await api(`/rest/v1/spark_profiles?select=*&id=eq.${state.user.id}`);state.profile=profiles[0]||null;state.busy=false;if(state.profile)await load();else render()}catch(error){state.busy=false;if(/email not confirmed/i.test(error.message)){state.pendingEmail=email;state.authMode='confirm';return notify('Confirm your email before signing in.')}notify(error.message)}}

  async function submitProfile(form){const data=new FormData(form),age=Number(data.get('age')),interests=data.getAll('interest').map(String),prompt_question=String(data.get('prompt_question')||''),prompt_answer=prompt_question?String(data.get('prompt_answer')||'').trim():'';if(!Number.isInteger(age)||age<18||age>100)return notify('You must be 18 or older to use Vibely.');if(interests.length>5||new Set(interests).size!==interests.length||interests.some(v=>!interestOptions.includes(v)))return notify('Choose up to five different interests.');if(prompt_question&&!promptOptions.includes(prompt_question))return notify('Choose a listed conversation prompt.');if(prompt_answer.length>180||(prompt_answer&&!prompt_question))return notify('Choose a prompt and keep your answer under 180 characters.');state.busy=true;try{const rows=await api('/rest/v1/spark_profiles','POST',{id:state.user.id,name:String(data.get('name')).trim(),age,gender:String(data.get('gender')),city:String(data.get('city')).trim(),bio:String(data.get('bio')).trim(),goal:String(data.get('goal')),interests,prompt_question,prompt_answer},{Prefer:'resolution=merge-duplicates,return=representation'});state.profile=rows[0];state.busy=false;state.view='discover';state.notice='';await load()}catch(error){state.busy=false;notify(error.message)}}

  async function submitPhoto(form){const file=form.querySelector('input[name="photo"]').files[0];if(!file)return notify('Choose a photo first.');if(state.busy)return;
    const own=galleryFor(state.user.id),slot=[0,1,2,3].find(i=>!own.some(photo=>photo.slot===i));if(slot===undefined)return notify('You can add up to four photos.');
    state.busy=true;let path=null,record=null;try{render();const blob=await photoBlob(file);path=`${state.user.id}/${crypto.randomUUID()}.webp`;
      await storageRequest(`spark-profile-photos/${storagePath(path)}`,'POST',blob,'image/webp');
      const rows=await api('/rest/v1/spark_profile_photos','POST',{owner_id:state.user.id,path,slot},{Prefer:'return=representation'});record=rows[0];if(!record)throw Error('Could not save gallery photo.');
      if(!state.profile.photo_path){const updated=await api(`/rest/v1/spark_profiles?id=eq.${state.user.id}`,'PATCH',{photo_path:path},{Prefer:'return=representation'});if(!updated.length)throw Error('Could not save the cover photo.');state.profile=updated[0];state.profiles=state.profiles.map(p=>p.id===state.user.id?state.profile:p)}
      state.photos.push(record);state.notice='Photo added to your gallery.';path=null;
    }catch(error){if(record)await api(`/rest/v1/spark_profile_photos?id=eq.${record.id}&owner_id=eq.${state.user.id}`,'DELETE').catch(()=>{});if(path)storageRequest('spark-profile-photos','DELETE',JSON.stringify({prefixes:[path]}),'application/json').catch(()=>{});state.notice=error.message}finally{state.busy=false;render()}
  }
  async function removePhoto(id){const photo=state.photos.find(p=>p.id===id&&p.owner_id===state.user.id);if(!photo||!await askConfirm('Remove this photo?','This removes it from your profile gallery.','Remove photo'))return;
    if(state.profile.photo_path===photo.path){const next=galleryFor(state.user.id).find(p=>p.id!==id);const updated=await api(`/rest/v1/spark_profiles?id=eq.${state.user.id}`,'PATCH',{photo_path:next?.path||null},{Prefer:'return=representation'});if(!updated.length)throw Error('Could not change the cover photo.');state.profile=updated[0];state.profiles=state.profiles.map(p=>p.id===state.user.id?state.profile:p)}
    await api(`/rest/v1/spark_profile_photos?id=eq.${id}&owner_id=eq.${state.user.id}`,'DELETE');state.photos=state.photos.filter(p=>p.id!==id);forgetPhoto({id:state.user.id,photo_path:photo.path});
    await storageRequest('spark-profile-photos','DELETE',JSON.stringify({prefixes:[photo.path]}),'application/json');state.notice='Photo removed.';render();
  }
  async function setCover(id){const photo=state.photos.find(p=>p.id===id&&p.owner_id===state.user.id);if(!photo)return;const rows=await api(`/rest/v1/spark_profiles?id=eq.${state.user.id}`,'PATCH',{photo_path:photo.path},{Prefer:'return=representation'});if(!rows.length)throw Error('Could not set cover photo.');state.profile=rows[0];state.profiles=state.profiles.map(p=>p.id===state.user.id?state.profile:p);state.notice='Cover photo updated.';render()}
  async function submitFilters(form){const data=new FormData(form),min=Number(data.get('min_age')),max=Number(data.get('max_age')),gender=String(data.get('gender_filter')),goal=String(data.get('goal_filter'));if(!Number.isInteger(min)||!Number.isInteger(max)||min<18||max>100||min>max)return notify('Choose a valid age range from 18 to 100.');if(!['All','Woman','Man','Nonbinary','Prefer not to say'].includes(gender)||!['All','Friends first','Open to a serious relationship','Getting to know people'].includes(goal))return notify('Choose a valid preference.');try{const rows=await api('/rest/v1/spark_discovery_preferences?on_conflict=owner_id','POST',{owner_id:state.user.id,min_age:min,max_age:max,gender_filter:gender,city_only:data.has('city_only'),goal_filter:goal},{Prefer:'resolution=merge-duplicates,return=representation'});state.preferences=rows[0];state.selected=0;state.notice='Discovery preferences saved.';render()}catch(error){notify(error.message)}}
  async function toggleDiscovery(){const paused=state.pausedIds.includes(state.user.id);if(paused)await api(`/rest/v1/spark_discovery_pauses?user_id=eq.${state.user.id}`,'DELETE');else await api('/rest/v1/spark_discovery_pauses','POST',{user_id:state.user.id});state.notice=paused?'Discovery resumed.':'Discovery paused. Existing matches can still chat.';await load()}
  async function submitSocial(form){const data=new FormData(form),platform=String(data.get('platform')),visibility=String(data.get('visibility'));if(!platforms.includes(platform)||!Object.hasOwn(visibilityLabels,visibility))return notify('Choose a platform and visibility.');let url;try{url=validatedSocialUrl(platform,data.get('url'))}catch(error){return notify(error.message)}try{await api('/rest/v1/spark_social_links?on_conflict=owner_id,platform','POST',{owner_id:state.user.id,platform,url,visibility},{Prefer:'resolution=merge-duplicates,return=representation'});state.notice='Social link saved with your chosen visibility.';await load()}catch(error){notify(error.message)}}
  async function act(action,id){try{state.notice='';if(action==='confirm-email'){state.authMode='confirm';return render()}if(action==='forgot-password'){state.authMode='recovery-request';return render()}if(action==='back-to-login'||action==='cancel-reset'){if(action==='cancel-reset'){state.session=null;state.user=null}state.authMode='login';return render()}if(action==='toggle-auth'){state.authMode=state.authMode==='signup'?'login':'signup';render();return}if(action==='sign-out'){try{await api('/auth/v1/logout','POST',{})}catch{}saveSession(null);state.user=null;state.profile=null;state.connections=[];state.profiles=[];state.unread={};state.latestMessages={};state.messages=[];state.reactions=[];state.chatPrefs=[];state.chatSearch='';state.photos=[];state.blocks=[];state.reports=[];state.suspensions=[];state.preferences=null;state.activityPrivacy=null;state.privateEntitlement=null;state.pausedIds=[];state.isModerator=false;Object.values(state.photoUrls).forEach(url=>URL.revokeObjectURL(url));Object.values(state.mediaUrls).forEach(url=>URL.revokeObjectURL(url));state.mediaUrls={};clearAttachment();state.photoUrls={};state.photoFailed.clear();render();return}if(action==='pick-photo'){return $('#livePhotoAttachment')?.click()}if(action==='take-photo'){return $('#liveCameraAttachment')?.click()}if(action==='emoji-picker'){const picker=$('#liveEmojiPicker');if(picker)picker.hidden=!picker.hidden;return}if(action==='insert-emoji'){const input=$('#liveMessageForm input[name=body]');if(input){input.value+=id;input.focus();$('#liveEmojiPicker').hidden=true}return}if(action==='record-audio'){return recordAudio()}if(action==='remove-attachment'){clearAttachment();return}if(action==='edit-profile'){state.profile={...state.profile};return setupScreen()}if(action==='discover'){state.view='discover';return render()}if(action==='delete-account')return deleteAccount();requireSignedIn();if(action==='profile'){state.view='profile';return render()}if(action==='premium'){state.view='premium';return render()}if(action==='toggle-private-activity')return togglePrivateActivity();if(action==='safety'){state.view='safety';return load()}if(action==='toggle-discovery')return toggleDiscovery();if(action==='moderation'){if(!state.isModerator)return;state.view='moderation';return load()}if(action==='review-report')return triageReport(id,'reviewed');if(action==='dismiss-report')return triageReport(id,'dismissed');if(action==='pause-member')return pauseMember(id);if(action==='restore-member')return restoreMember(id);if(action==='remove-photo')return removePhoto(id);if(action==='cover-photo')return setCover(id);if(action==='view-photo'){const photo=state.photos.find(p=>p.id===id);if(photo){state.galleryIndex[photo.owner_id]=id;render()}return}if(action==='edit-social'){const link=state.links.find(x=>x.id===id&&x.owner_id===state.user.id);if(!link)return;$('#liveSocialPlatform').value=link.platform;$('#liveSocialUrl').value=link.url;$('#liveSocialVisibility').value=link.visibility;$('#liveSocialForm').scrollIntoView({behavior:'smooth',block:'center'});$('#liveSocialUrl').focus();return}if(action==='remove-social'){const link=state.links.find(x=>x.id===id&&x.owner_id===state.user.id);if(!link||!await askConfirm(`Remove ${link.platform}?`,'This removes the link from your profile. You can add it again later.','Remove link'))return;await api(`/rest/v1/spark_social_links?id=eq.${encodeURIComponent(id)}&owner_id=eq.${state.user.id}`,'DELETE',null,{Prefer:'return=representation'});state.notice='Social link removed.';return load()}if(action==='skip'){state.selected++;return render()}if(action==='intro'){if(state.sendingIntro)return;state.sendingIntro=true;try{const list=discoveryCandidates();const p=list[state.selected%list.length];if(!p)return;const intro=await askText(`Say hello to ${p.name}`,'A thoughtful note makes it easier to start a conversation.',300);if(!intro)return;await api('/rest/v1/spark_connections','POST',{requester_id:state.user.id,recipient_id:p.id,intro,status:'pending'});state.selected=0;state.notice='Your intro was sent.';return load()}finally{state.sendingIntro=false}}if(action==='accept'||action==='decline'){const status=action==='accept'?'accepted':'declined';const rows=await api(`/rest/v1/spark_connections?id=eq.${encodeURIComponent(id)}&status=eq.pending`,'PATCH',{status},{Prefer:'return=representation'});if(!rows.length)throw Error('That request is no longer pending.');if(action==='accept'){state.view='chats';state.activeChat=id}return load()}if(action==='pin-chat'||action==='mute-chat'){const field=action==='pin-chat'?'pinned':'muted',old=state.chatPrefs.find(p=>p.connection_id===id),next=!old?.[field];const rows=old?await api(`/rest/v1/spark_chat_preferences?owner_id=eq.${state.user.id}&connection_id=eq.${encodeURIComponent(id)}`,'PATCH',{[field]:next},{Prefer:'return=representation'}):await api('/rest/v1/spark_chat_preferences','POST',{owner_id:state.user.id,connection_id:id,[field]:true},{Prefer:'return=representation'});if(!rows?.length)throw Error('Conversation setting was not saved.');state.chatPrefs=state.chatPrefs.filter(p=>p.connection_id!==id).concat(rows[0]);state.notice=field==='pinned'?(next?'Conversation pinned.':'Conversation unpinned.'):(next?'Conversation muted. Unread messages remain in its chat.':'Conversation unmuted.');return render()}if(action==='reaction-picker'){const m=state.messages.find(m=>m.id===id);if(!m)return;const host=$('#modalRoot');host.innerHTML=`<div class="modal-backdrop"><div class="modal live-dialog live-reaction-dialog" role="dialog" aria-modal="true"><h2>React to message</h2><div class="live-reaction-options">${['❤️','😂','👍','🥰','🔥','👏'].map(e=>`<button data-live="react-message" data-id="${esc(id)}|${e}" aria-label="React ${e}">${e}</button>`).join('')}</div><button class="live-outline" data-live="close-reactions">Cancel</button></div></div>`;return}if(action==='close-reactions'){$('#modalRoot').innerHTML='';return}if(action==='react-message'){const [messageId,emoji]=String(id||'').split('|');$('#modalRoot').innerHTML='';const m=state.messages.find(m=>m.id===messageId),old=state.reactions.find(r=>r.message_id===messageId&&r.user_id===state.user.id);if(!m||!['❤️','😂','👍','🥰','🔥','👏'].includes(emoji))return;if(old?.emoji===emoji)await api(`/rest/v1/spark_message_reactions?message_id=eq.${messageId}&user_id=eq.${state.user.id}`,'DELETE');else if(old)await api(`/rest/v1/spark_message_reactions?message_id=eq.${messageId}&user_id=eq.${state.user.id}`,'PATCH',{emoji});else await api('/rest/v1/spark_message_reactions','POST',{message_id:messageId,connection_id:m.connection_id,user_id:state.user.id,emoji});await loadMessages();const box=$('#liveMessages');if(box)box.innerHTML=messagesHtml();return}if(action==='select-chat'){clearAttachment();state.activeChat=id;await loadMessages();return render()}if(action==='block'){if(!await askConfirm('Block this member?','You will no longer see each other or exchange messages.','Block member'))return;await api('/rest/v1/spark_blocks','POST',{blocker_id:state.user.id,blocked_id:id,blocked_name:person(id).name.slice(0,40)});state.activeChat=null;state.selected=0;state.notice='Member blocked.';return load()}if(action==='unblock'){if(!await askConfirm('Unblock this member?','You may see each other again in discovery.','Unblock'))return;await api(`/rest/v1/spark_blocks?blocker_id=eq.${state.user.id}&blocked_id=eq.${encodeURIComponent(id)}`,'DELETE');state.notice='Member unblocked.';return load()}if(action==='end-match'){if(!await askConfirm('End this match?','This closes the conversation for both people.','End match'))return;const rows=await api(`/rest/v1/spark_connections?id=eq.${encodeURIComponent(id)}&status=eq.accepted`,'PATCH',{status:'blocked'},{Prefer:'return=representation'});if(!rows.length)throw Error('This match is no longer active.');state.activeChat=null;state.notice='Match ended.';return load()}if(action==='report-message'){const message=state.messages.find(m=>m.id===id&&m.sender_id!==state.user.id),match=state.connections.find(c=>c.id===state.activeChat&&c.status==='accepted');if(!message||!match||message.sender_id!==otherId(match))return;const report=await askReport(person(message.sender_id).name,message.body);if(!report)return;await api('/rest/v1/spark_reports','POST',{reporter_id:state.user.id,reported_id:message.sender_id,message_id:message.id,...report});return notify('Message reported. A moderator can review the saved context.')}if(action==='report'){const report=await askReport(person(id).name);if(!report)return;await api('/rest/v1/spark_reports','POST',{reporter_id:state.user.id,reported_id:id,...report});return notify('Report submitted. Thank you for helping keep Vibely safe.')}}catch(error){notify(error.message)}}
  document.addEventListener('click',event=>{const nav=event.target.closest('[data-view]'),button=event.target.closest('[data-live]');if(!nav&&!button)return;event.preventDefault();event.stopImmediatePropagation();if(nav){if(!state.profile)return;state.view=nav.dataset.view;state.notice='';if(state.view==='chats')loadChatSummaries().then(loadMessages).then(render).catch(error=>notify(error.message));else if(state.view==='likes')load().catch(error=>notify(error.message));else render();return}act(button.dataset.live,button.dataset.id)},true);
  document.addEventListener('submit',event=>{const form=event.target;if(!['liveAuthForm','liveResendForm','liveRecoveryForm','liveResetForm','liveProfileForm','liveMessageForm','liveSocialForm','livePhotoForm','liveFiltersForm'].includes(form.id))return;event.preventDefault();event.stopImmediatePropagation();if(form.id==='liveResendForm'){resendConfirmation(form.querySelector('#liveEmail').value.trim());return}if(form.id==='liveRecoveryForm'){requestRecovery(form.querySelector('#liveEmail').value.trim());return}if(form.id==='liveResetForm'){updatePassword(form.querySelector('#liveNewPassword').value,form.querySelector('#liveConfirmPassword').value);return}if(form.id==='liveAuthForm'){const email=form.querySelector('#liveEmail').value,password=form.querySelector('#livePassword').value;submitAuth({email:{value:email},password:{value:password}});return}if(form.id==='liveProfileForm'){submitProfile(form);return}if(form.id==='liveSocialForm'){submitSocial(form);return}if(form.id==='livePhotoForm'){submitPhoto(form);return}if(form.id==='liveFiltersForm'){submitFilters(form);return}sendMessage(form)},true);
  document.addEventListener('input',event=>{if(event.target.id==='liveChatSearch'){state.chatSearch=event.target.value.trim().toLocaleLowerCase();updateChatList()}},true);
  document.addEventListener('change',event=>{if(['livePhotoAttachment','liveCameraAttachment'].includes(event.target.id)){chooseAttachment(event.target.files?.[0]);event.target.value=''}},true);
  setInterval(async()=>{if(!state.user||!state.profile||document.hidden)return;try{if(state.view==='chats'){await loadMessages();const box=$('#liveMessages');if(box){box.innerHTML=messagesHtml();box.scrollTop=box.scrollHeight}}else if(state.view==='likes'){const data=await api('/rest/v1/spark_connections?select=*&order=created_at.desc&limit=200');if(JSON.stringify(data)!==JSON.stringify(state.connections)){state.connections=data;render()}}}catch{}},5000);
  setInterval(async()=>{if(!state.user||!state.profile||document.hidden)return;try{await loadUnread();if(state.view==='chats')await loadChatSummaries()}catch{}},15000);
  document.addEventListener('visibilitychange',()=>{if(document.hidden||!state.user||!state.profile)return;loadUnread().then(()=>{if(state.view==='chats')return loadChatSummaries().then(loadMessages).then(()=>{const box=$('#liveMessages');if(box){box.innerHTML=messagesHtml();box.scrollTop=box.scrollHeight}})}).catch(()=>{})});
  window.sparkLive={enabled:true,render,start:restore,getAuth:()=>({user:state.user,session:state.session,profile:state.profile})};
})();
